// =====================================================================
// BLOQUES S1 / C0 · Inicializacion (comun a ambas placas)
// diagramas/flujo_servidor.md S1 · diagramas/flujo_cliente.md C0
// ---------------------------------------------------------------------
// Descripcion: se ejecuta una vez al desplegar el flujo. Verifica que
//   settings.js haya cargado los modulos compartidos y que config.js sea
//   la version que este flujo espera, y lleva los dos LED a su estado
//   seguro (apagados) antes de que exista cualquier dato.
// Entrada: msg del inject de arranque; msg.payload = nombre del modulo
//   OPC UA que esta placa necesita ('servidorOpcua' | 'clienteOpcua').
// Salidas: [1] LED digital (payload 0) · [2] LED PWM (payload 0 %).
// Excepciones: si falta un modulo, informa con node.error() y no envia
//   nada: un nodo mal desplegado avisa, no se comporta a medias.
// =====================================================================
const VERSION_CONFIG_REQUERIDA = 1;

const config = global.get('config');
const senales = global.get('senales');
const faltantes = ['config', 'senales', 'opcua', 'pdciRutas', String(msg.payload)].filter((n) => !global.get(n));
if (faltantes.length > 0) {
    node.error('settings.js no cargo: ' + faltantes.join(', ') + ' (ver node-red/README.md §3)');
    node.status({ fill: 'red', shape: 'dot', text: 'falta ' + faltantes.join(', ') });
    return null;
}
if (config.VERSION !== VERSION_CONFIG_REQUERIDA) {
    // Igual que en la Tarea 1: un nodo con configuracion vieja arranca
    // avisando, no aborta.
    node.warn('config.js version ' + config.VERSION + ', este flujo espera ' + VERSION_CONFIG_REQUERIDA);
}
node.status({ fill: 'green', shape: 'dot', text: 'config v' + config.VERSION });
return [{ payload: 0 }, { payload: senales.dutyAPorcentajePiGpiod(0) }];

// =====================================================================
// BLOQUE S3 · Rampa diente de sierra — Raspberry Pi 1
// diagramas/flujo_servidor.md, bloque S3 · consigna Parte 2.3
// ---------------------------------------------------------------------
// Descripcion: cada 50 ms (inject "S3 · Tick") calcula el valor de la
//   sierra 0-65535 de periodo 4 s A PARTIR DEL RELOJ (senales.sierra) y lo
//   envia a S2 para publicarlo en Servidor.Rampa.
//   Los botones "S3 · Detener rampa" / "S3 · Reanudar rampa" envian
//   msg.topic = 'pausa' (true/false): con la rampa detenida el valor queda
//   fijo y la suscripcion solo emite KeepAlive (consigna Parte 3.4).
// Entrada: msg del inject de 50 ms, o { topic: 'pausa', payload: boolean }.
// Salida: { topic: 'rampa', payload: UInt16, instante: Date } -> S2.
// Excepciones: ninguna (senales.sierra solo falla con una config invalida,
//   que prueba_senales.js descarta antes del despliegue).
//
// Firma: senales.sierra(tMs: number, periodoMs: number, tickMs: number,
//   maximo?: number) : number
// =====================================================================
if (msg.topic === 'pausa') {
    const pausada = msg.payload === true;
    flow.set('rampaPausada', pausada);
    node.status(pausada ? { fill: 'grey', shape: 'ring', text: 'rampa detenida' } : {});
    node.log(new Date().toISOString() + ' rampa ' + (pausada ? 'DETENIDA' : 'reanudada'));
    return null;
}
// Detenida: no se publica nada, asi el valor (y su SourceTimestamp) no cambia.
if (flow.get('rampaPausada')) return null;

const config = global.get('config');
const senales = global.get('senales');
const instante = new Date();
const valor = senales.sierra(instante.getTime(), config.senales.periodoSierraMs, config.senales.tickMs,
    config.senales.maximo);
flow.set('rampaGenerada', valor); // para la consola (S7)
return { topic: 'rampa', payload: valor, instante };

// =====================================================================
// BLOQUES S4 / C5 · Lectura del pulsador local (comun a ambas placas)
// diagramas/flujo_servidor.md S4 · diagramas/flujo_cliente.md C5
// ---------------------------------------------------------------------
// Descripcion: convierte el nivel del GPIO en el Boolean del modelo. El
//   pulsador va a GND con pull-up interno: nivel 0 = presionado. El
//   antirrebote lo hace pigpio (set_glitch_filter, 25 000 us) antes de que
//   llegue el mensaje.
// Entrada: msg.payload 0 | 1 desde "pi gpiod in" (un mensaje por flanco).
// Salida: { topic: 'pulsador', payload: boolean, instante: Date }
//   -> S2 (servidor: publica Servidor.EstadoPulsador)
//   -> C1 (cliente: escribe Cliente.EstadoPulsador)
// Registro: una linea 'LATENCIA pulsador_local=...' por flanco.
// Excepciones: un payload que no sea 0/1 se descarta con advertencia.
// =====================================================================
const nivel = Number(msg.payload);
if (nivel !== 0 && nivel !== 1) {
    node.warn('nivel GPIO invalido: ' + msg.payload);
    return null;
}
const presionado = nivel === 0; // activo en bajo
const instante = new Date();
flow.set('pulsadorLocal', presionado);
// Marca para medir la latencia pulsador -> LED de la otra placa (Parte 3.4):
// se compara con la linea "LED digital" del otro equipo, con los relojes
// sincronizados por chrony (node-red/README.md §14).
node.log('LATENCIA pulsador_local=' + (presionado ? 'ON' : 'OFF') + ' t=' + instante.toISOString());
return { topic: 'pulsador', payload: presionado, instante };

// =====================================================================
// BLOQUES S3 y S4 -> S2 · Publicacion de los datos del servidor
// diagramas/flujo_servidor.md
// ---------------------------------------------------------------------
// Descripcion: recibe la rampa (S3) y el pulsador (S4) y los publica en
//   Servidor.Rampa y Servidor.EstadoPulsador con setValueFromSource(), que
//   fija el SourceTimestamp en el instante de generacion.
// Entrada: msg.topic 'rampa' (payload 0-65535) o 'pulsador' (boolean);
//   msg.instante (Date) opcional.
// Salidas: ninguna (las escrituras del cliente salen desde On Start).
// Excepciones: si el servidor no termino de arrancar, el dato se descarta
//   y se cuenta: el siguiente tick lo reemplaza.
// =====================================================================
const controlador = context.get('controlador');
if (!controlador) {
    context.set('descartados', (context.get('descartados') || 0) + 1);
    return null;
}
const instante = msg.instante instanceof Date ? msg.instante : new Date();
if (msg.topic === 'rampa') {
    controlador.publicarRampa(msg.payload, instante);
} else if (msg.topic === 'pulsador') {
    controlador.publicarPulsador(msg.payload === true, instante);
    node.status({ fill: 'green', shape: msg.payload ? 'dot' : 'ring', text: 'pulsador ' + (msg.payload ? 'ON' : 'OFF') });
}
return null;

initialize:
// =====================================================================
// BLOQUES S2 y S5 · Servidor OPC UA — "On Start" de la function node
// diagramas/flujo_servidor.md, bloques S2 (espacio de direcciones) y
// S5 (atencion de escrituras)
// ---------------------------------------------------------------------
// Descripcion: crea y arranca el servidor con
//   servidor_opcua.iniciarServidor() y deja el controlador en el contexto
//   del nodo. Cada escritura del cliente sale por las salidas 1/2.
// Salidas: [1] Cliente.EstadoPulsador (payload boolean)
//          [2] Cliente.Rampa (payload 0-65535)
//          [3] eventos de sesion y canal (payload texto)
// Excepciones: si el puerto 4840 sigue ocupado por el despliegue
//   anterior (EADDRINUSE) reintenta hasta 10 veces cada 500 ms; cualquier
//   otro error se informa en el estado del nodo.
//
// Firma de la biblioteca (consigna: "especificar parametros con tipo"):
//   iniciarServidor({ opcua: object, config: object, directorioPki: string,
//     credenciales: {usuario: string, hashClave: string} | null,
//     alEscribirCliente: (nombre: string, valor: boolean|number,
//                         dataValue: DataValue) => void,
//     registrar: (texto: string) => void }) : Promise<Controlador>
// =====================================================================
const config = global.get('config');
const opcua = global.get('opcua');
const modulo = global.get('servidorOpcua');
const rutas = global.get('pdciRutas');
const leerCredenciales = global.get('pdciCredencialesServidor');

// [SEC] Las credenciales se leen del entorno en el momento, a traves de una
// funcion: el hash nunca queda guardado en el contexto global, que el
// editor de Node-RED muestra en la barra lateral.
const cred = typeof leerCredenciales === 'function' ? leerCredenciales() : null;
const credenciales = cred && cred.usuario && cred.hashClave ? cred : null;
if (!credenciales) node.warn('sin OPCUA_USUARIO/OPCUA_CLAVE_HASH: solo acceso anonimo');

node.status({ fill: 'yellow', shape: 'ring', text: 'iniciando' });

const esperar = (ms) => new Promise((r) => setTimeout(r, ms));
let controlador = null;
for (let intento = 1; intento <= 10 && !controlador; intento++) {
    try {
        controlador = await modulo.iniciarServidor({
            opcua,
            config,
            directorioPki: rutas.pkiServidor,
            credenciales,
            // ---- BLOQUE S5: atencion de escrituras ----------------------
            alEscribirCliente: (nombre, valor, dataValue) => {
                flow.set(nombre, {
                    valor,
                    sourceTimestamp: dataValue.sourceTimestamp,
                    serverTimestamp: dataValue.serverTimestamp,
                });
                const m = { topic: nombre, payload: valor };
                node.send(nombre === 'clientePulsador' ? [m, null, null] : [null, m, null]);
            },
            registrar: (texto) => {
                node.log(texto);
                node.send([null, null, { topic: 'evento', payload: texto }]);
            },
        });
    } catch (error) {
        if (error.code === 'EADDRINUSE' && intento < 10) {
            await esperar(500);
        } else {
            node.status({ fill: 'red', shape: 'dot', text: error.message });
            node.error('no se pudo iniciar el servidor OPC UA: ' + error.message);
            break;
        }
    }
}

if (controlador) {
    context.set('controlador', controlador);
    for (const e of controlador.endpoints()) node.log('Endpoint: ' + e);
    node.status({ fill: 'green', shape: 'dot', text: 'escuchando :' + config.red.puertoOpcUa });
}

finalize:
// =====================================================================
// BLOQUE S2 · Servidor OPC UA — "On Close" de la function node
// ---------------------------------------------------------------------
// Descripcion: detiene el servidor al redesplegar o al detener Node-RED.
//   On Close es sincrono en Node-RED: se lanza el cierre sin esperarlo y
//   sin demora de cortesia (detener(0)), para liberar el puerto 4840 lo
//   antes posible. Si el nuevo despliegue llega antes, On Start reintenta.
// =====================================================================
const controlador = context.get('controlador');
if (controlador) {
    controlador.detener(0).catch((e) => node.warn('cierre del servidor: ' + e.message));
    context.set('controlador', undefined);
}

func:
// =====================================================================
// BLOQUES S6 / C4 · LED digital (comun a ambas placas)
// diagramas/flujo_servidor.md S6 · diagramas/flujo_cliente.md C4
// ---------------------------------------------------------------------
// Descripcion: el LED digital refleja el EstadoPulsador del OTRO equipo
//   (servidor: Cliente.EstadoPulsador; cliente: Servidor.EstadoPulsador).
// Entrada: msg.payload boolean.
// Salida: msg.payload 1 | 0 -> "pi gpiod out" en modo digital.
// Registro: una linea 'LATENCIA led_digital=...' por cada cambio.
// Excepciones: un payload que no sea boolean se descarta: nunca se
//   enciende un actuador con un dato de tipo dudoso.
// =====================================================================
if (msg.payload !== true && msg.payload !== false) {
    node.warn('EstadoPulsador no booleano: ' + msg.payload);
    return null;
}
node.status({ fill: msg.payload ? 'green' : 'grey', shape: 'dot', text: msg.payload ? 'ON' : 'OFF' });
// Marca para medir la latencia (Parte 3.4): solo cuando el LED CAMBIA. En
// Modo A llega el mismo valor 10 veces por segundo; registrar cada uno
// inundaria el registro y no aporta nada.
if (context.get('ultimo') !== msg.payload) {
    context.set('ultimo', msg.payload);
    node.log('LATENCIA led_digital=' + (msg.payload ? 'ON' : 'OFF') + ' t=' + new Date().toISOString());
}
return { payload: msg.payload ? 1 : 0 };

// =====================================================================
// BLOQUES S6 / C4 · LED PWM (comun a ambas placas)
// diagramas/flujo_servidor.md S6 · diagramas/flujo_cliente.md C4
// consigna Partes 2.4 y 3.7
// ---------------------------------------------------------------------
// Descripcion: escala la Rampa recibida del OTRO equipo (UInt16) a ciclo
//   de trabajo 0-255, con correccion gamma opcional (config.senales), y
//   la convierte al porcentaje que espera "pi gpiod out" en modo PWM.
// Entrada: msg.payload entero 0-65535.
// Salida: msg.payload porcentaje 0-100 (exacto para pigpio, ver
//   senales.dutyAPorcentajePiGpiod); msg.duty con el 0-255 para la traza.
// Excepciones: un valor fuera de rango se descarta con advertencia.
//
// Firmas: senales.escala255(valor: number, maximo?: number,
//   gamma?: number) : number · senales.dutyAPorcentajePiGpiod(duty: number)
//   : number
// =====================================================================
const config = global.get('config');
const senales = global.get('senales');
if (!senales.esUInt16(msg.payload)) {
    node.warn('Rampa fuera de rango: ' + msg.payload);
    return null;
}
const gamma = config.senales.usarGamma ? config.senales.gamma : 1;
const duty = senales.escala255(msg.payload, config.senales.maximo, gamma);
return { payload: senales.dutyAPorcentajePiGpiod(duty), duty };

// =====================================================================
// BLOQUE S7 · Registro en consola — Raspberry Pi 1
// diagramas/flujo_servidor.md, bloque S7 · consigna Parte 3.5
// ---------------------------------------------------------------------
// Descripcion: una vez por segundo imprime la rampa que genera esta placa,
//   la que recibe del cliente (Cliente.Rampa) y el SourceTimestamp de ese
//   dato. Va a node.log(): en la RPi sale por "journalctl -u nodered" y por
//   la consola de node-red-log, sin pasar por el editor.
// Entrada: msg del inject "S7 · Cada 1 s".
// Salida: msg.payload con la linea (para un nodo debug opcional).
// Excepciones: ninguna.
//
// Por que 1 s y no cada tick: imprimir 20 lineas por segundo suma carga
// al mismo event loop que genera las senales (el "efecto sonda" de la
// Tarea 1).
// =====================================================================
const generada = flow.get('rampaGenerada');
const recibido = flow.get('clienteRampa');
const ts = recibido && recibido.sourceTimestamp ? new Date(recibido.sourceTimestamp).toISOString() : 'sin dato';
const linea = 'SERVIDOR generada=' + (generada === undefined ? '-' : generada) +
    ' recibida(Cliente.Rampa)=' + (recibido ? recibido.valor : '-') +
    ' SourceTimestamp=' + ts;
node.log(linea);
return { payload: linea };
